  try {
    const response = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${cityName}&units=metric&appid=YOUR_API_KEY`);
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Error fetching weather data:', error);
    return null;
  }
};

const getWeatherData = async (cityName) => {
  if (weatherCache.has(cityName)) {
    console.log('Returning cached data for', cityName);
    return weatherCache.get(cityName);
  }

  const data = await fetchWeatherData(cityName);
  if (data) {
    weatherCache.set(cityName, data);
  }
  return data;
};
